 let p,s,selected,mode='note',focused=null,clueFilter='all',history=[],future=[],highlights=new Set(),errors=new Set(),zoom=100,baseCell=55,cellSize=55,gesture=null,pdfURL=null,pdfBlob=null,lastTick=Date.now(),refId=0,refs=new Map(),noteTimer=null,saveTimer=null,toastTimer=null;
