 document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();actions[a.dataset.action]?.();return;}const b=e.target.closest('[data-tool]');if(b){mode=b.dataset.tool;if(mode==='mark'){openDialog('临时推理符号','<p>符号只是你的临时标记，不计入人物位置。</p><div class="button-row">'+['?','○','△','★'].map(x=>`<button class="outline" data-symbol="${x}" style="font-size:25px">${x}</button>`).join('')+'</div>',[{label:'关闭',action:closeDialog}]);$$('[data-symbol]').forEach(el=>el.onclick=()=>{settings.markSymbol=el.dataset.symbol;write('settings',settings);closeDialog();renderTools();});}renderTools();return;}const per=e.target.closest('[data-person]');if(per){if(suppressedPersonClick){suppressedPersonClick=false;return;}select(per.dataset.person);return;}const clue=e.target.closest('[data-toggle-clue]');if(clue){const id=clue.dataset.toggleClue;change(()=>{s.done=s.done.includes(id)?s.done.filter(x=>x!==id):[...s.done,id];});return;}const filter=e.target.closest('[data-filter]');if(filter){clueFilter=filter.dataset.filter;renderClues();}const ref=e.target.closest('[data-ref]');if(ref){setHighlight(refs.get(+ref.dataset.ref));}});
