 function actionAt(i,type,add){let active=selected;if(type==='target'&&p.rules.treasure){active=p.people.find(x=>x.treasure).id;type='place';}if(!active&&['note','place'].includes(type)){toast(t('Select a portrait first.','请先选择一个人物头像。'));return;}if(p.cells[i].blocked&&!person(active)?.canOccupyBlocked&&['note','place'].includes(type)){toast(t('This object cannot be occupied by a person.','人物不能占据这个物品格；宝藏可以。'));return;}s=E.apply(p,s,{type,index:i,person:active,add,allowBlocked:!settings.noXBlocked,symbol:settings.markSymbol||'?'});focused=i;errors.clear();renderBoard();renderPeople();}

 function finishGesture(cancel=false){if(!gesture)return;clearTimeout(gesture.timer);const g=gesture;gesture=null;if(g.pan)return;if(cancel){restore(g.before);render();return;}if(!g.applied){actionAt(g.start,g.type,g.add);g.applied=true;feedback();}if(JSON.stringify(g.before)!==JSON.stringify(snapshot())){history.push(g.before);history=history.slice(-150);future=[];queueSave();}render();}
 $('#board').addEventListener('pointerdown',e=>{if(e.button!==0)return;if(s.paused){toast('请先继续调查');return;}const cell=e.target.closest('[data-cell]');if(!cell)return;const i=+cell.dataset.cell;focused=i;if(e.altKey){e.preventDefault();showCellMemo(i);return;}e.preventDefault();$('#board-viewport').focus({preventScroll:true});const v=$('#board-viewport');gesture={start:i,last:i,type:mode,before:snapshot(),applied:false,visited:new Set([i]),pan:mode==='pan',x:e.clientX,y:e.clientY,sx:v.scrollLeft,sy:v.scrollTop};if(gesture.pan)return;gesture.add=mode==='note'?!(s.notes[i]||[]).includes(selected):!s.cross.includes(i);if(mode==='note')gesture.timer=setTimeout(()=>{if(gesture&&!gesture.applied){actionAt(i,'place');gesture.applied=true;gesture.held=true;feedback();}},450);renderBoard();});
 document.addEventListener('pointermove',e=>{if(!gesture)return;const g=gesture;if(g.pan){$('#board-viewport').scrollLeft=g.sx-(e.clientX-g.x);$('#board-viewport').scrollTop=g.sy-(e.clientY-g.y);return;}const cell=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-cell]');if(!cell)return;const i=+cell.dataset.cell;if(i===g.start&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<8)return;if(i!==g.start)clearTimeout(g.timer);if(g.held||g.type==='place'||g.type==='target'||g.type==='mark')return;if(!g.applied){actionAt(g.start,g.type,g.add);g.applied=true;}if(!g.visited.has(i)){g.visited.add(i);actionAt(i,g.type,g.add);}g.last=i;});
