 document.addEventListener('keydown',e=>{if(e.target.closest('[data-toggle-clue]'))return;if($('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;const k=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&k==='z'){e.preventDefault();actions[e.shiftKey?'redo':'undo']();return;}if((e.ctrlKey||e.metaKey)&&k==='y'){e.preventDefault();actions.redo();return;}if(e.ctrlKey||e.metaKey)return;if(k==='?'){showHelp();return;}if(k==='/'){e.preventDefault();showSearch();return;}if(k==='p'){actions.pause();return;}if(k==='+'||k==='='){zoomBy(25);return;}if(k==='-'){zoomBy(-25);return;}if(k==='['||k===']'){const i=p.people.findIndex(x=>x.id===selected);select(p.people[(i+(k===']'?1:p.people.length-1))%p.people.length].id);return;}const keyModes={'1':'note','2':'place',x:'cross',e:'erase',m:'mark',t:'target',h:'pan'};if(keyModes[k]){mode=keyModes[k];renderTools();return;}if(k.startsWith('arrow')){e.preventDefault();let i=focused??0,r=Math.floor(i/p.size),c=i%p.size;if(k==='arrowup')r=Math.max(0,r-1);if(k==='arrowdown')r=Math.min(p.size-1,r+1);if(k==='arrowleft')c=Math.max(0,c-1);if(k==='arrowright')c=Math.min(p.size-1,c+1);focused=r*p.size+c;renderBoard();$(`[data-cell="${focused}"]`).scrollIntoView({block:'nearest',inline:'nearest'});return;}if(focused!=null&&[' ','enter','delete','backspace'].includes(k)){e.preventDefault();change(()=>actionAt(focused,k==='enter'?'place':['delete','backspace'].includes(k)?'erase':mode));}});
